package ai.eva.android.probe;
import org.json.*;import java.util.*;

/** Presentation of server-reported account limits. Unknown fields never imply zero usage. */
final class AccountQuota {
 static String number(double n){return n==Math.rint(n)?String.valueOf((long)n):String.format(Locale.ROOT,"%.1f",n);}
 static String reset(long seconds){return seconds>0?android.text.format.DateFormat.format("MM-dd HH:mm",seconds*1000).toString():"服务端未提供";}
 static String window(JSONObject w,String fallback){if(w==null)return "";long mins=w.optLong("windowDurationMins",0);String name=mins>0?(mins%1440==0?mins/1440+" 天额度":mins%60==0?mins/60+" 小时额度":mins+" 分钟额度"):fallback;double used=w.optDouble("usedPercent",Double.NaN);return name+"\n"+(Double.isFinite(used)&&used>=0?"剩余 "+number(Math.max(0,100-used))+"% · 已用 "+number(used)+"%":"使用比例暂不可读取")+"\n重置时间："+reset(w.optLong("resetsAt",0))+"\n";}
 static String snapshot(JSONObject s,String fallback){StringBuilder text=new StringBuilder(s.optString("limitName",fallback));text.append("\n");String primary=window(s.optJSONObject("primary"),"主要额度"),secondary=window(s.optJSONObject("secondary"),"次要额度");text.append(primary).append(secondary);if(primary.isEmpty()&&secondary.isEmpty())text.append("服务端未提供额度窗口\n");JSONObject credits=s.optJSONObject("credits");if(credits!=null){if(credits.optBoolean("unlimited"))text.append("额外额度：不限额（服务端标记）\n");else if(!credits.isNull("balance"))text.append("额外额度余额：").append(credits.optString("balance")).append("\n");else if(credits.has("hasCredits"))text.append(credits.optBoolean("hasCredits")?"有额外额度，余额未提供\n":"无额外额度\n");}JSONObject individual=s.optJSONObject("individualLimit");if(individual!=null){text.append("个人支出上限：").append(individual.optString("limit","未提供")).append(" · 已使用：").append(individual.optString("used","未提供")).append("\n");double remaining=individual.optDouble("remainingPercent",Double.NaN);if(Double.isFinite(remaining))text.append("支出额度剩余：").append(number(remaining)).append("%\n");text.append("支出额度重置：").append(reset(individual.optLong("resetsAt",0))).append("\n");}return text.toString();}
 static String describe(JSONObject quota){if(quota==null)return "额度暂不可读取，请点击刷新重试。";StringBuilder text=new StringBuilder();JSONObject groups=quota.optJSONObject("rateLimitsByLimitId");boolean any=false;if(groups!=null){Iterator<String> keys=groups.keys();while(keys.hasNext()){String key=keys.next();JSONObject s=groups.optJSONObject(key);if(s!=null){text.append(snapshot(s,key)).append("\n");any=true;}}}if(!any){JSONObject s=quota.optJSONObject("rateLimits");if(s!=null)text.append(snapshot(s,"Codex 账号额度"));else text.append("服务端未返回额度明细\n");}if(!quota.isNull("ordinaryUsageAllowed"))text.append("普通额度当前可用：").append(quota.optBoolean("ordinaryUsageAllowed")?"是":"否").append("\n");text.append("更新时间：").append(android.text.format.DateFormat.format("HH:mm:ss",System.currentTimeMillis()));return text.toString();}
}
